import Foundation
import QuickrCore
import QuickrTestSupport
import Testing

@testable import QuickrData

/// N1 (notifications.md §4.3, §4.4): Swift computes the server's descriptors, actions, hash inputs,
/// category ids and `fmt` byte for byte. Every case of shared/fixtures/notification-vectors.json
/// (generated by backend/tests/test_notification_vectors.py, B7).
@Suite(.timeLimit(.minutes(2))) struct NotificationVectorTests {
    static let vectors: Vectors = {
        do {
            return try JSONDecoder().decode(Vectors.self, from: Fixtures.data("notification-vectors.json"))
        } catch {
            fatalError("notification-vectors.json: \(error)")
        }
    }()

    @Test func hasTheVectors() {
        #expect(Self.vectors.cases.count >= 30)
        #expect(Self.vectors.fmt.count >= 21)
        #expect(Self.vectors.meta.maxLabelLength == NotificationCategory.maxLabelLength)
    }

    @Test(arguments: vectors.cases)
    func category(_ vector: Case) throws {
        let category = NotificationCategory(
            serverId: vector.serverId, topicId: vector.topicId, version: vector.version,
            questions: vector.questions.map { $0.toDomain() }, counts: vector.counts, last: vector.last)
        #expect(category?.descriptor == vector.expected.quickLog, "\(vector.name): descriptor")
        #expect(category?.actions ?? [] == vector.expected.actions, "\(vector.name): actions")
        #expect(category?.id == vector.expected.categoryId, "\(vector.name): category id")
        #expect(
            category.map { NotificationCategory.hashInput($0.actions) } == vector.expected.hashInput, "\(vector.name)")
        #expect(category?.bodySuffix ?? "" == vector.expected.bodySuffix, "\(vector.name): body suffix")
        // The push's own descriptor (decoded from its JSON) renders the same category.
        if let quickLog = vector.expected.quickLog {
            let fromPush = NotificationCategory(
                serverId: vector.serverId, topicId: vector.topicId, version: vector.version, descriptor: quickLog)
            #expect(fromPush.id == vector.expected.categoryId)
            let reencoded = try JSONDecoder().decode(QuickLogDescriptor.self, from: JSONEncoder().encode(quickLog))
            #expect(reencoded == quickLog, "\(vector.name): the descriptor survives JSON")
        }
    }

    /// The cut's boundary, which the vectors (all far longer) don't pin: 64 scalars stay, 65 don't.
    @Test func labelsAreCutPastSixtyFourScalars() {
        let sixtyFour = String(repeating: "é", count: 64)
        #expect(NotificationCategory.cut(sixtyFour) == sixtyFour)
        let cut = NotificationCategory.cut(sixtyFour + "x")
        #expect(cut.unicodeScalars.count == 64 && cut.hasSuffix("…") && cut.dropLast() == sixtyFour.dropLast())
    }

    /// Beyond the vectors: across the whole binary64 range, fmt round-trips exactly, is canonical
    /// and never writes an exponent (a fixed-seed walk over random bit patterns).
    @Test func fmtRoundTripsAcrossTheRange() {
        var state: UInt64 = 0x9E37_79B9_7F4A_7C15
        var checked = 0
        while checked < 5000 {
            state = state &* 6_364_136_223_846_793_005 &+ 1_442_695_040_888_963_407
            let x = Double(bitPattern: state)
            guard x.isFinite else { continue }
            let text = NumberFormat.fmt(x)
            #expect(Double(text) == x, "\(x) → \(text)")
            #expect(NumberFormat.isCanonical(text) && !text.contains("e"), "\(x) → \(text)")
            checked += 1
        }
    }

    @Test(arguments: vectors.fmt)
    func fmt(_ vector: Fmt) {
        #expect(NumberFormat.fmt(vector.number) == vector.expected, "\(vector.number)")
        #expect(NumberFormat.isCanonical(vector.expected))
        #expect(!NumberFormat.isCanonical(vector.expected + "\n") && !NumberFormat.isCanonical("\n" + vector.expected))
    }

    // MARK: - The file

    struct Vectors: Decodable {
        var cases: [Case]
        var fmt: [Fmt]
        var meta: Meta

        struct Meta: Decodable {
            var maxLabelLength: Int
            enum CodingKeys: String, CodingKey { case maxLabelLength = "max_label_length" }
        }
    }

    struct Case: Decodable, Sendable, CustomTestStringConvertible {
        var name: String
        var serverId: String
        var topicId: String
        var version: Int
        var questions: [QuestionDTO]
        var counts: [String: Int]
        var last: AnswerValue?
        var expected: Expected

        var testDescription: String { name }

        struct Expected: Decodable, Sendable {
            var actions: [NotificationCategory.Action]
            var bodySuffix: String
            var categoryId: String?
            var hashInput: String?
            var quickLog: QuickLogDescriptor?

            enum CodingKeys: String, CodingKey {
                case actions
                case bodySuffix = "body_suffix"
                case categoryId = "category_id"
                case hashInput = "hash_input"
                case quickLog = "quick_log"
            }
        }

        enum CodingKeys: String, CodingKey {
            case name, version, questions, counts, last, expected
            case serverId = "server_id"
            case topicId = "topic_id"
        }

        init(from decoder: any Decoder) throws {
            let c = try decoder.container(keyedBy: CodingKeys.self)
            name = try c.decode(String.self, forKey: .name)
            serverId = try c.decode(String.self, forKey: .serverId)
            topicId = try c.decode(String.self, forKey: .topicId)
            version = try c.decode(Int.self, forKey: .version)
            questions = try c.decode([QuestionDTO].self, forKey: .questions)
            counts = try c.decode([String: Int].self, forKey: .counts)
            expected = try c.decode(Expected.self, forKey: .expected)
            // An answer as the store holds it: an int stays exact; a string or a bool isn't a number.
            if try c.decodeNil(forKey: .last) {
                last = nil
            } else if let n = try? c.decode(Int.self, forKey: .last) {
                last = .int(n)
            } else if let x = try? c.decode(Double.self, forKey: .last) {
                last = .double(x)
            } else if let s = try? c.decode(String.self, forKey: .last) {
                last = .string(s)
            } else {
                last = .string("not a number")
            }
        }
    }

    struct Fmt: Decodable, Sendable, CustomTestStringConvertible {
        var number: QuickLogNumber
        var expected: String

        var testDescription: String { "\(number) → \(expected)" }

        enum CodingKeys: String, CodingKey { case kind, value, bits, expected }

        init(from decoder: any Decoder) throws {
            let c = try decoder.container(keyedBy: CodingKeys.self)
            expected = try c.decode(String.self, forKey: .expected)
            if try c.decode(String.self, forKey: .kind) == "int" {
                number = .int(try c.decode(Int.self, forKey: .value))
            } else {
                // Built from the IEEE 754 bits, so no JSON parser rounds it on the way.
                let bits = try c.decode(String.self, forKey: .bits)
                number = .double(Double(bitPattern: UInt64(bits, radix: 16)!))
            }
        }
    }
}
